  function track(init, keys) {
    const ks = keys.map((k, i) => ({ t: k[0], v: k[1], d: k[2] == null ? 0.3 : k[2], e: EASE[k[3] || 'inOut'] || EASE.inOut, i })).sort((a, b) => a.t - b.t || a.i - b.i);
    const isArr = Array.isArray(init);
    const lv = (a, b, k) => (isArr ? a.map((v, i) => v + (b[i] - v) * k) : a + (b - a) * k);
    const ev = (k, t) => (k.d <= 0 || t >= k.t + k.d ? k.v : lv(k.from, k.v, k.e(Math.max(0, (t - k.t) / k.d))));
    ks.forEach((k, i) => { k.from = i === 0 ? init : ev(ks[i - 1], k.t); });
    return (t) => { let cur = null; for (const k of ks) { if (k.t <= t) cur = k; else break; } return cur ? ev(cur, t) : init; };
  }
  function stepTrack(init, keys) {   
    const ks = keys.map((k) => ({ t: k[0] + (k[2] || 0) / 2, v: k[1] })).sort((a, b) => a.t - b.t);
    return (t) => { let v = init; for (const k of ks) { if (k.t <= t) v = k.v; else break; } return v; };
  }

   
  const DEF = {};
