  const gaze = (id, seq, end) => {
    const look = [], turn = [];
    for (const [t, who, d] of seq) { const [lk, tn] = AT[id][who]; look.push(K(t, lk, d || 0.18, 'out')); turn.push(K(t + 0.08, tn, (d || 0.18) + 0.2, 'inOut')); }
    look.push(K(end, 'base', 0.4)); turn.push(K(end, 'base', 0.45));
    return { look, turn };
  };
  const nod = (t, k = 1) => ({ bend: [K(t, 4 * k, 0.15, 'out'), K(t + 0.18, 0, 0.3)], lookY: [K(t, 0.4, 0.15, 'out'), K(t + 0.18, 0.1, 0.3)] });
