        armB: [K(2.6, 'openLo', 0.35), K(4.4, 'palmsUp', 0.3, 'back'), K(5.6, 'shrug', 0.35, 'back'), K(6.9, 'base', 0.5)],
        lean: [K(0.4, 2.5, 0.4), K(3.3, 4.5, 0.6), K(4.6, 6, 0.4), K(6.6, 'base', 0.7)],
        brow: [K(0.9, 4, 0.15, 'out'), K(1.2, 1, 0.3), K(2.7, 6, 0.2), K(3.4, 2, 0.3), K(4.4, 8, 0.3), K(6.6, 'base', 0.6)],
